class Solution {
    vector<int> maxSingle(const vector<int>& nums, int count) {
        vector<int> stack;
        int drop = nums.size() - count;
        for (int x : nums) {
            while (drop > 0 && !stack.empty() && stack.back() < x) {
                stack.pop_back();
                drop--;
            }
            stack.push_back(x);
        }
        stack.resize(count);
        return stack;
    }
    bool greaterVec(const vector<int>& a, int i, const vector<int>& b, int j) {
        while (i < (int)a.size() && j < (int)b.size() && a[i] == b[j]) {
            i++; j++;
        }
        return j == (int)b.size() || (i < (int)a.size() && a[i] > b[j]);
    }
    vector<int> merge(const vector<int>& a, const vector<int>& b) {
        vector<int> res;
        int i = 0, j = 0;
        while (i < (int)a.size() || j < (int)b.size()) {
            if (greaterVec(a, i, b, j)) {
                res.push_back(a[i++]);
            } else {
                res.push_back(b[j++]);
            }
        }
        return res;
    }
