class Solution {
    public int[] maxNumber(int[] nums1, int[] nums2, int k) {
        int[] best = new int[k];
        int m = nums1.length, n = nums2.length;
        boolean first = true;
        for (int i = Math.max(0, k - n); i <= Math.min(k, m); i++) {
            int[] cand = merge(maxSingle(nums1, i), maxSingle(nums2, k - i), k);
            if (first || greater(cand, 0, best, 0)) {
                best = cand;
                first = false;
            }
        }
        return best;
    }
    private int[] maxSingle(int[] nums, int count) {
        int[] stack = new int[count];
        int top = -1, drop = nums.length - count;
        for (int x : nums) {
            while (drop > 0 && top >= 0 && stack[top] < x) {
                top--;
                drop--;
            }
            if (top < count - 1) stack[++top] = x;
            else drop--;
        }
        return stack;
    }
    private int[] merge(int[] a, int[] b, int k) {
        int[] res = new int[k];
        int i = 0, j = 0, idx = 0;
        while (idx < k) {
            if (greater(a, i, b, j)) res[idx++] = a[i++];
            else res[idx++] = b[j++];
        }
        return res;
    }
    private boolean greater(int[] a, int i, int[] b, int j) {
        while (i < a.length && j < b.length && a[i] == b[j]) {
            i++; j++;
        }
        return j == b.length || (i < a.length && a[i] > b[j]);
    }
}

