var maxNumber = function(nums1, nums2, k) {
    const maxSingle = (nums, count) => {
        const stack = [];
        let drop = nums.length - count;
        for (const x of nums) {
            while (drop > 0 && stack.length > 0 && stack[stack.length - 1] < x) {
                stack.pop();
                drop--;
            }
            stack.push(x);
        }
        return stack.slice(0, count);
    };
    const greater = (a, i, b, j) => {
        while (i < a.length && j < b.length && a[i] === b[j]) {
            i++; j++;
        }
        return j === b.length || (i < a.length && a[i] > b[j]);
    };
    const merge = (a, b) => {
        const res = [];
        let i = 0, j = 0;
        while (i < a.length || j < b.length) {
            if (greater(a, i, b, j)) res.push(a[i++]);
            else res.push(b[j++]);
        }
        return res;
    };
    let best = [];
    const m = nums1.length, n = nums2.length;
    for (let i = Math.max(0, k - n); i <= Math.min(k, m); i++) {
        const cand = merge(maxSingle(nums1, i), maxSingle(nums2, k - i));
        if (best.length === 0 || greater(cand, 0, best, 0)) {
            best = cand;
        }
    }
    return best;
};
